import{ax as s,A as i,aQ as n,z as e}from"./chunks/framework.BWRXlwpK.js";const k=JSON.parse('{"title":"缓存雪崩","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"redis/cache-avalanche.md","filePath":"redis/cache-avalanche.md","lastUpdated":1788148933000}'),t={name:"redis/cache-avalanche.md"};function p(l,a,h,d,o,c){return e(),i("div",null,a[0]||(a[0]=[n(`<h1 id="缓存雪崩" tabindex="-1">缓存雪崩 <a class="header-anchor" href="#缓存雪崩" aria-label="Permalink to &quot;缓存雪崩&quot;">​</a></h1><p>大量缓存在同一时间失效，导致大量请求同时访问数据库，从而造成数据库压力过大甚至宕机。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Redis宕机也属于雪崩</p></div><h2 id="栗子" tabindex="-1">栗子 <a class="header-anchor" href="#栗子" aria-label="Permalink to &quot;栗子&quot;">​</a></h2><p>假设有 Redis：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>user:1</span></span>
<span class="line"><span>user:2</span></span>
<span class="line"><span>user:3</span></span>
<span class="line"><span>goods:1001</span></span>
<span class="line"><span>goods:1002</span></span>
<span class="line"><span>shop:001</span></span>
<span class="line"><span>config:system</span></span></code></pre></div><p>平时命中率 95%，数据库压力很小。</p><p>在设定中数据的过期时间是 <code>30分钟</code>，在系统启动时同时进行了缓存。</p><p>例如：<code>12：00</code> 进行缓存，那么数据将在 <code>12：30</code> 过期。</p><p>此时有 50000 个请求同时到达，由于缓存已经过期，这些请求全都打到了数据库上，数据库瞬间被压垮。</p><p>这就是</p><blockquote><p>缓存雪崩</p></blockquote><h2 id="缓存穿透-击穿-雪崩-的区别" tabindex="-1">缓存穿透 / 击穿 / 雪崩 的区别 <a class="header-anchor" href="#缓存穿透-击穿-雪崩-的区别" aria-label="Permalink to &quot;缓存穿透 / 击穿 / 雪崩 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>Key数量</th><th>数据是否存在</th></tr></thead><tbody><tr><td>缓存穿透</td><td>很多不存在的Key</td><td>不存在</td></tr><tr><td>缓存击穿</td><td>一个热点Key</td><td>存在</td></tr><tr><td>缓存雪崩</td><td>大量Key</td><td>存在</td></tr></tbody></table><h2 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h2><h3 id="方案1-随机过期时间-最常用" tabindex="-1">方案1：随机过期时间（最常用） <a class="header-anchor" href="#方案1-随机过期时间-最常用" aria-label="Permalink to &quot;方案1：随机过期时间（最常用）&quot;">​</a></h3><p>不要设定成同一的过期时间，当在同一时间缓存时很容易造成缓存雪崩。</p><p>而是通过 <code>固定时间 + 随机数</code> 的方式设置过期时间。</p><p>例如</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 30分钟 + 随机数</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ttl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Random.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nextInt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">redis.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(key, value, ttl, TimeUnit.MINUTES);</span></span></code></pre></div><h3 id="方案2-热点数据永不过期" tabindex="-1">方案2：热点数据永不过期 <a class="header-anchor" href="#方案2-热点数据永不过期" aria-label="Permalink to &quot;方案2：热点数据永不过期&quot;">​</a></h3><p>适用于：</p><ul><li>系统配置</li><li>店铺信息</li><li>省市数据</li><li>菜单数据</li></ul><p>这些很长时间都不会发生变化的数据，完全可以设置成 <code>永久缓存</code>。</p><p>修改时删除缓存，等待下载重新加载即可。</p><h3 id="方案3-多级缓存" tabindex="-1">方案3：多级缓存 <a class="header-anchor" href="#方案3-多级缓存" aria-label="Permalink to &quot;方案3：多级缓存&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器缓存</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Nginx缓存</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Redis</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>MySQL</span></span></code></pre></div><p>不把鸡蛋放在同一个篮子里，即使 Redis 挂掉，前面还有其他缓存，大型网站经常这样做。</p><h3 id="方案4-限流降级" tabindex="-1">方案4：限流降级 <a class="header-anchor" href="#方案4-限流降级" aria-label="Permalink to &quot;方案4：限流降级&quot;">​</a></h3><p>数据库压力过大：</p><p>比如有 1000000 个请求进入，只接受其中 1000 个请求，其余的返回错误信息。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;msg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;系统繁忙，请稍后重试&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>常见组件：</p><ul><li>Sentinel</li><li>Gateway 限流</li></ul>`,34)]))}const u=s(t,[["render",p]]);export{k as __pageData,u as default};
